  snorri: { n: 'Snorri Sturluson', p: 'Reykholt, Island', d: 'Isländsk hövding som skrev Snorra-Eddan — nästan allt vi vet om nordisk mytologi — och Heimskringla, kungasagorna; mördad i sin egen källare.' },
  an_lushan: { n: 'An Lushan-upproret', p: 'Chang’an, Kina', d: 'En generals uppror krossar Tang-Kinas guldålder — efter vissa beräkningar den dödligaste katastrofen i mänsklighetens historia dittills.' },
  tang: { n: 'Tangdynastin', p: 'Chang’an, Kina', d: 'Kosmopolitiska Chang’an är världens största stad; poesi, tryckkonst och Sidenvägen kulminerar i Kinas kosmopolitiska guldålder.' },
  kievan_rus: { n: 'Kyivriket', p: 'Kyiv', d: 'Fursten Oleg erövrar Kyiv och gör staden till huvudstad i ett rike från Östersjön till Svarta havet — den medeltida stat, med centrum i dagens Kyiv, som ukrainare, belarusier och ryssar alla spårar sitt ursprung till.' },
  kyiv_founding: { n: 'Kyivs mytiska grundande', p: 'Kyiv', d: 'Nestorskrönikan nämner bröderna Kyj, Sjtjek och Choryv och syster Lybid som grundare; år 482 är det konventionella datumet, antaget vid stadens 1 500-årsjubileum 1982.' },
  volodymyr: { n: 'Volodymyr den store', p: 'Kyiv', d: 'Storfursten som smidde Kyivriket till ett rike av europeiskt format — antog därefter den bysantinska kristendomen och döpte sitt rike in i en ny civilisation.' },
  christianization_rus: { n: 'Kyivrikets dop', p: 'Dnipro, Kyiv', d: 'Volodymyr döper Kyivs befolkning kollektivt i Dnipro och förmäler rusländerna med den bysantinska tron, litteraturen och konsten för de följande tusen åren.' },
