  sophia_kyiv: { n: 'Sankt Sofia i Kyiv invigs', p: 'Kyiv', d: 'Jaroslavs trettonkupoliga katedral med gyllene mosaiker blir rusrikets andliga och politiska hjärta — och, 988 år senare, Ukrainas emblem.' },
