  kyiv_sack_1169: { n: 'Kyiv plundras av Suzdal-koalitionen', p: 'Kyiv', d: 'En furstlig koalition från norr, samlad av Andrej Bogoljubskij av Vladimir, stormar och plundrar ”rusrikets städers moder” — Kyiv återfår aldrig sin ledande ställning när riket splittras.' },
  kyiv_sack_1240: { n: 'Mongolerna intar Kyiv', p: 'Kyiv', d: 'Batu khans härar gör slut på Kyivrikets era i december 1240; staden ligger i ruiner i ett århundrade och rusländernas vägar klyvs — under Horden, och i väster, åtskilda.' },
  galicia_volhynia: { n: 'Riket Galizien–Volynien', p: 'Halych, Ukraina', d: 'Rusrikets fortsättning i väster: fursten Roman enar Halych och Volynien; 1253 kröns hans son Danylo till kung av en påvlig utsänd. Den sista självständiga russtaten gör motstånd mot Horden tills Polen och Litauen tar upp den (1340-talet).' },
  danylo: { n: 'Kung Danylo av Galizien', p: 'Halych & Chelm', d: 'Grundare av Lviv (omkr. 1256) och byggare av ett rike av befästa städer; krönt till ”Rutheniens kung” 1253 — knäböjde aldrig för Gyllene horden.' },
  blue_waters: { n: 'Slaget vid Blå vattnen', p: 'Syni Vody, Ukraina', d: 'Storfursten Algirdas av Litauen krossar Gyllene hordens armé; Kyiv och Dnipro-länderna går till storfurstendömet — en litauisk-ruthensk stat vars lagar skrevs på det ruthenska språk som talades i Ukraina och Vitryssland.' },
  livonian_crusade: { n: 'Norra korstågen i Östersjön', p: 'Livland (Lettland/Estland)', d: 'Svärdsriddarordnar och biskopsfurstar erövrar Livland och Estland med eld och svärd; Gamla Preussen och Kurland faller också — bara litauerna hejdar korståget och förblir hedniska i ytterligare ett århundrade.' },
  riga_founded: { n: 'Riga grundas', p: 'Riga, Lettland', d: 'Biskop Albert grundar Riga vid Daugavas mynning; staden går med i Hansan 1282 och dominerar Östersjöhandeln i århundraden.' },
