  finland_sweden: { n: 'Finland under svenska kronan', p: 'Åbo, Finland', d: 'Det svenska korståget (traditionellt 1249) inleder 560 år av finsk historia inom Sverige; Åbo domkyrka och borg förankrar kyrkan, lagen och handeln.' },
  mindaugas_crown: { n: 'Mindaugas kröns — Litauens kungarike', p: 'Kernavė, Litauen', d: 'Den 6 juli 1253 kröns den hedniske härskaren Mindaugas till Litauens förste och ende kung; mördad 1263, men hans enade rike överlever honom som storfurstendöme.' },
  gdl: { n: 'Storfurstendömet Litauen', p: 'Vilnius, Litauen', d: 'Från Östersjön nästan till Svarta havet: i två århundraden Europas största stat — hedniskt ursprung, lagar skrivna på ruthenska, intar Kyiv 1362 — tills unionen i Lublin förenar det med Polen.' },
  gediminas: { n: 'Storfursten Gediminas', p: 'Vilnius, Litauen', d: 'Grundare av Vilnius (först omnämnt i hans brev från 1323 som bjöd in köpmän och hantverkare av alla trosbekännelser) och av den dynasti som ska härska över Litauen, Polen och Ungern.' },
