  kyiv_mohyla: { n: 'Kyiv-Mohyla-akademien grundas', p: 'Kyiv', d: 'Metropoliten Petro Mohyla fogar Kyivs brödraskolsskola samman med lavranskolan till ett kollegium — Östeuropas intellektuella kraftstation i 150 år framåt.' },
